import * as React from "react"
import { mergeProps } from "@base-ui/react/merge-props"
import { useRender } from "@base-ui/react/use-render"
import { cn } from "cn"

import "./typeset.css"

type TypographySize = "sm" | "default" | "lg"

const sizes = (sm: string, md: string, lg: string) => ({
  sm,
  default: md,
  lg,
})

function Typography({
  className,
  size = "default",
  render,
  ...props
}: useRender.ComponentProps<"div"> & { size?: TypographySize }) {
  return useRender({
    defaultTagName: "div",
    props: mergeProps<"div">(
      {
        className: cn(
          "typeset",
          sizes(
            "[--typeset-flow:1.125em] [--typeset-leading:1.7] [--typeset-size:0.875rem]",
            "[--typeset-flow:1.25em] [--typeset-leading:1.75] [--typeset-size:1rem]",
            "[--typeset-flow:1.5em] [--typeset-leading:1.8] [--typeset-size:1.125rem]"
          )[size],
          className
        ),
      },
      props
    ),
    render,
    state: {
      slot: "typography",
      size,
    },
  })
}

const typographyH1Sizes = sizes("text-3xl", "text-4xl", "text-5xl")

function TypographyH1({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"h1"> & { size?: TypographySize }) {
  return (
    <h1
      data-slot="typography-h1"
      data-size={size}
      className={cn(
        "font-semibold tracking-tight scroll-m-20 font-heading text-balance",
        typographyH1Sizes[size],
        className
      )}
      {...props}
    />
  )
}

const typographyH2Sizes = sizes("text-2xl", "text-3xl", "text-4xl")

function TypographyH2({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"h2"> & { size?: TypographySize }) {
  return (
    <h2
      data-slot="typography-h2"
      data-size={size}
      className={cn(
        "font-semibold tracking-tight scroll-m-20 font-heading first:mt-0",
        typographyH2Sizes[size],
        className
      )}
      {...props}
    />
  )
}

const typographyH3Sizes = sizes("text-xl", "text-2xl", "text-3xl")

function TypographyH3({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"h3"> & { size?: TypographySize }) {
  return (
    <h3
      data-slot="typography-h3"
      data-size={size}
      className={cn(
        "font-semibold tracking-tight scroll-m-20 font-heading",
        typographyH3Sizes[size],
        className
      )}
      {...props}
    />
  )
}

const typographyH4Sizes = sizes("text-lg", "text-xl", "text-2xl")

function TypographyH4({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"h4"> & { size?: TypographySize }) {
  return (
    <h4
      data-slot="typography-h4"
      data-size={size}
      className={cn(
        "font-semibold tracking-tight scroll-m-20 font-heading",
        typographyH4Sizes[size],
        className
      )}
      {...props}
    />
  )
}

const typographyPSizes = sizes("text-sm", "text-base", "text-lg")

function TypographyP({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"p"> & { size?: TypographySize }) {
  return (
    <p
      data-slot="typography-p"
      data-size={size}
      className={cn(
        "leading-7 [&:not(:first-child)]:mt-6",
        typographyPSizes[size],
        className
      )}
      {...props}
    />
  )
}

const typographyLeadSizes = sizes("text-base", "text-lg", "text-xl")

function TypographyLead({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"p"> & { size?: TypographySize }) {
  return (
    <p
      data-slot="typography-lead"
      data-size={size}
      className={cn(
        "text-muted-foreground",
        typographyLeadSizes[size],
        className
      )}
      {...props}
    />
  )
}

const typographyASizes = sizes("text-sm", "text-base", "text-lg")

function TypographyA({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"a"> & { size?: TypographySize }) {
  return (
    <a
      data-slot="typography-a"
      data-size={size}
      className={cn(
        "font-medium text-primary underline underline-offset-4",
        typographyASizes[size],
        className
      )}
      {...props}
    />
  )
}

const typographyBlockquoteSizes = sizes("text-sm", "text-base", "text-lg")

function TypographyBlockquote({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"blockquote"> & { size?: TypographySize }) {
  return (
    <blockquote
      data-slot="typography-blockquote"
      data-size={size}
      className={cn(
        "mt-6 border-s-2 ps-6 italic",
        typographyBlockquoteSizes[size],
        className
      )}
      {...props}
    />
  )
}

const typographyInlineCodeSizes = sizes("text-xs", "text-sm", "text-base")

function TypographyInlineCode({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"code"> & { size?: TypographySize }) {
  return (
    <code
      data-slot="typography-inline-code"
      data-size={size}
      className={cn(
        "rounded bg-muted font-mono font-semibold relative px-[0.3rem] py-[0.2rem]",
        typographyInlineCodeSizes[size],
        className
      )}
      {...props}
    />
  )
}

const typographyListItemSizes = sizes("text-sm", "text-base", "text-lg")

function TypographyListItem({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"li"> & { size?: TypographySize }) {
  return (
    <li
      data-slot="typography-list-item"
      data-size={size}
      className={cn("mt-2", typographyListItemSizes[size], className)}
      {...props}
    />
  )
}

const typographyTableRowSizes = sizes("text-sm", "text-base", "text-lg")

function TypographyTableRow({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"tr"> & { size?: TypographySize }) {
  return (
    <tr
      data-slot="typography-table-row"
      data-size={size}
      className={cn(
        "m-0 border-t p-0 even:bg-muted",
        typographyTableRowSizes[size],
        className
      )}
      {...props}
    />
  )
}

const typographyTableHeadSizes = sizes("text-sm", "text-base", "text-lg")

function TypographyTableHead({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"th"> & { size?: TypographySize }) {
  return (
    <th
      data-slot="typography-table-head"
      data-size={size}
      className={cn(
        "border-b border-border px-4 py-3 text-start font-semibold [&[align=center]]:text-center [&[align=left]]:text-left [&[align=right]]:text-right",
        typographyTableHeadSizes[size],
        className
      )}
      {...props}
    />
  )
}

const typographyTableCellSizes = sizes("text-sm", "text-base", "text-lg")

function TypographyTableCell({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"td"> & { size?: TypographySize }) {
  return (
    <td
      data-slot="typography-table-cell"
      data-size={size}
      className={cn(
        "border-t border-border px-4 py-3 text-start align-middle [&[align=center]]:text-center [&[align=left]]:text-left [&[align=right]]:text-right",
        typographyTableCellSizes[size],
        className
      )}
      {...props}
    />
  )
}

const typographyListSizes = sizes("text-sm", "text-base", "text-lg")

// The list type changes its markers, so it is a prop instead of a render.
function TypographyList({
  className,
  as = "ul",
  size = "default",
  ...props
}: React.ComponentProps<"ol"> & {
  as?: "ul" | "ol"
  size?: TypographySize
}) {
  // A <ul> takes the attributes of an <ol> except start and reversed.
  const Tag = as as "ol"
  return (
    <Tag
      data-slot="typography-list"
      data-size={size}
      data-ordered={as === "ol" ? "" : undefined}
      className={cn(
        "my-6 ms-6",
        as === "ol" ? "list-decimal" : "list-disc",
        typographyListSizes[size],
        className
      )}
      {...props}
    />
  )
}

const typographyTableSizes = sizes("text-sm", "text-base", "text-lg")

function TypographyTable({
  className,
  containerClassName,
  size = "default",
  ...props
}: React.ComponentProps<"table"> & {
  containerClassName?: string
  size?: TypographySize
}) {
  return (
    <div
      data-slot="typography-table-container"
      data-size={size}
      className={cn(
        "rounded-xl border border-border my-6 w-full overflow-x-auto",
        containerClassName
      )}
    >
      <table
        data-slot="typography-table"
        data-size={size}
        className={cn(
          "w-full border-collapse",
          typographyTableSizes[size],
          className
        )}
        {...props}
      />
    </div>
  )
}

export {
  Typography,
  TypographyA,
  TypographyBlockquote,
  TypographyH1,
  TypographyH2,
  TypographyH3,
  TypographyH4,
  TypographyInlineCode,
  TypographyLead,
  TypographyList,
  TypographyListItem,
  TypographyP,
  TypographyTable,
  TypographyTableCell,
  TypographyTableHead,
  TypographyTableRow,
}

@layer components {
  /*
   * shadcn/typeset
   * https://ui.shadcn.com/docs/typeset.
   */
  .typeset {
    --typeset-font-body: inherit;
    --typeset-font-heading: var(--font-heading);
    --typeset-font-mono: var(--font-mono);
    --typeset-size: 1em;
    --typeset-leading: 1.75;
    --typeset-flow: 1.25em;
  }
}

@layer components {
  .typeset {
    font-family: var(--typeset-font-body);
    font-size: calc(var(--typeset-size) * 1.125);
    line-height: var(--typeset-leading);
    color: var(--color-foreground, currentColor);
    overflow-wrap: break-word;
    margin-trim: block-start;

    @media (min-width: 48rem), print {
      font-size: var(--typeset-size);
    }

    --typeset-muted: var(
      --color-muted-foreground,
      color-mix(in oklab, currentColor 60%, transparent)
    );
    --typeset-rule: var(
      --color-border,
      color-mix(in oklab, currentColor 20%, transparent)
    );
  }

  .typeset
    *:not(
      :where(
        .not-typeset,
        [data-not-typeset],
        .not-typeset *,
        [data-not-typeset] *
      )
    ) {
    &:where(p) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
    }
    &:where(h1, h2, h3, h4, h5, h6) {
      color: var(--color-foreground, currentColor);
      font-family: var(--typeset-font-heading);
      font-weight: 600;
      margin-block-end: 0;
    }
    &:where(h1) {
      font-size: 1.75em;
      line-height: 1.3;
      margin-block-start: var(--typeset-flow);
    }
    &:where(h2) {
      font-size: 1.25em;
      line-height: 1.4;
      margin-block-start: calc(var(--typeset-flow) * 1.4);
    }
    &:where(h3) {
      font-size: 1.125em;
      line-height: 1.45;
      margin-block-start: var(--typeset-flow);
    }
    &:where(h4) {
      font-size: 1em;
      line-height: 1.5;
      margin-block-start: var(--typeset-flow);
    }
    &:where(h5) {
      font-size: 0.875em;
      line-height: 1.5;
      font-weight: 500;
      color: var(--typeset-muted);
      margin-block-start: calc(var(--typeset-flow) / 0.875);
    }
    &:where(h6) {
      font-size: 0.8125em;
      line-height: 1.5;
      font-weight: 500;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--typeset-muted);
      margin-block-start: calc(var(--typeset-flow) / 0.8125);
    }
    &:where([id]) {
      scroll-margin-block-start: var(--typeset-flow);
    }
    &:where(h1 + *, h2 + *, h3 + *, h4 + *, h5 + *, h6 + *) {
      margin-block-start: 1em;
    }
    &:where(:is(h1, h2, h3, h4) :is(code)) {
      font-size: 0.9em;
    }
    &:where(a) {
      color: inherit;
      font-weight: 500;
      text-decoration-line: underline;
      text-decoration-color: color-mix(in oklab, currentColor 30%, transparent);
    }
    &:where(a:hover) {
      text-decoration-color: currentColor;
    }
    &:where(a:focus-visible) {
      outline: 2px solid var(--color-ring, currentColor);
      outline-offset: 2px;
      border-radius: 0.125em;
    }
    &:where(:is(h1, h2, h3, h4, h5, h6) :is(a)) {
      font-weight: inherit;
    }
    &:where(strong, b) {
      font-weight: 600;
    }
    &:where(:is(h1, h2, h3, h4) :is(strong, b)) {
      font-weight: 600;
    }
    &:where(mark) {
      background-color: color-mix(
        in oklab,
        oklch(0.86 0.17 95) 40%,
        transparent
      );
      color: inherit;
      padding: 0.05em 0.15em;
      border-radius: 0.2em;
    }
    &:where(abbr[title]) {
      text-decoration-line: underline;
      text-decoration-style: dotted;
      text-underline-offset: 0.2em;
      cursor: help;
    }
    &:where(del, s) {
      color: var(--typeset-muted);
      text-decoration-line: line-through;
    }
    &:where(sup, sub) {
      font-size: 0.75em;
      line-height: 0;
      position: relative;
      vertical-align: baseline;
    }
    &:where(sup) {
      top: -0.5em;
    }
    &:where(sub) {
      bottom: -0.25em;
    }
    &:where(sup a) {
      text-decoration-line: none;
      font-weight: 500;
    }
    &:where(ul) {
      list-style-type: disc;
    }
    &:where(ol) {
      list-style-type: decimal;
    }
    &:where(ul ul) {
      list-style-type: circle;
    }
    &:where(ul ul ul) {
      list-style-type: square;
    }
    &:where(ol[type="a" i]) {
      list-style-type: lower-alpha;
    }
    &:where(ol[type="i" i]) {
      list-style-type: lower-roman;
    }
    &:where(ol[type="A" s]) {
      list-style-type: upper-alpha;
    }
    &:where(ol[type="I" s]) {
      list-style-type: upper-roman;
    }
    &:where(ul, ol) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
      padding-inline-start: 1.5em;
    }
    &:where(li) {
      margin-block-start: 0.5em;
      padding-inline-start: 0.4em;
    }
    &:where(li > p, li > ul, li > ol) {
      margin-block-start: 0.5em;
    }
    &:where(ul > li)::marker,
    &:where(ol > li)::marker {
      color: var(--typeset-muted);
    }
    &:where(ul.contains-task-list) {
      list-style-type: none;
      padding-inline-start: 0.25em;
    }
    &:where(li.task-list-item > input[type="checkbox"]) {
      margin-inline-end: 0.5em;
      vertical-align: -0.1em;
      accent-color: var(--color-primary, currentColor);
    }
    &:where(details) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
    }
    &:where(summary) {
      cursor: pointer;
      font-weight: 500;
    }
    &:where(summary)::marker {
      color: var(--typeset-muted);
    }
    &:where(kbd) {
      font-family: inherit;
      font-size: 0.85em;
      font-weight: 500;
      border: 1px solid var(--typeset-rule);
      border-block-end-width: 2px;
      border-radius: min(calc(var(--radius, 0.5em) * 0.6), 0.35em);
      padding: 0.0625em 0.35em;
    }
    &:where(dl) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
    }
    &:where(dt) {
      font-weight: 500;
      margin-block-start: 1em;
    }
    &:where(dt + dt) {
      margin-block-start: 0.25em;
    }
    &:where(dd) {
      margin-block-start: 0.25em;
      margin-inline-start: 0;
      padding-inline-start: 1em;
      color: var(--typeset-muted);
    }
    &:where(:not(pre) > code) {
      background-color: var(
        --color-muted,
        color-mix(in oklab, currentColor 8%, transparent)
      );
      font-family: var(--typeset-font-mono);
      font-size: 0.85em;
      border-radius: min(calc(var(--radius, 0.5em) * 0.6), 0.35em);
      padding: 0.125em 0.3em;
    }
    &:where(pre) {
      background-color: var(
        --color-muted,
        color-mix(in oklab, currentColor 8%, transparent)
      );
      font-family: var(--typeset-font-mono);
      font-size: 0.875em;
      line-height: 1.5;
      tab-size: 2;
      direction: ltr;
      border-radius: var(--radius, 0.5em);
      padding: 0.75em 1em;
      overflow-x: auto;
      margin-block-start: calc(var(--typeset-flow) / 0.875);
      margin-block-end: 0;
    }
    &:where(pre code) {
      background-color: transparent;
      font-family: inherit;
      font-size: inherit;
      padding: 0;
      border-radius: 0;
    }
    &:where(blockquote) {
      border-inline-start: 2px solid var(--typeset-rule);
      padding-inline-start: 1em;
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
      margin-inline: 0;
    }
    &:where(hr) {
      border: 0;
      border-block-start: 1px solid var(--typeset-rule);
      margin-block-start: calc(var(--typeset-flow) * 2.4);
      margin-block-end: 0;
    }
    &:where(hr + h1, hr + h2, hr + h3, hr + h4) {
      margin-block-start: var(--typeset-flow);
    }
    &:where(.footnotes, [data-footnotes]) {
      margin-block-start: calc(var(--typeset-flow) * 2);
      border-block-start: 1px solid var(--typeset-rule);
      padding-block-start: var(--typeset-flow);
      font-size: 0.875em;
      color: var(--typeset-muted);
    }
    &:where(math[display="block"]) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
      overflow-x: auto;
      overflow-y: hidden;
      padding-block: 0.25em;
    }
    &:where(img, video) {
      border-radius: var(--radius, 0.5em);
      max-width: 100%;
      height: auto;
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
    }
    &:where(p img) {
      margin-block-start: 0;
    }
    &:where(figure) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
      margin-inline: 0;
    }
    &:where(figcaption, caption) {
      color: var(--typeset-muted);
      font-size: 0.875em;
      text-align: center;
      margin-block-start: calc(0.75em / 0.875);
    }
    &:where(caption) {
      caption-side: bottom;
    }
    &:where(table) {
      max-width: 100%;
      font-size: 1em;
      line-height: 1.5;
      font-variant-numeric: tabular-nums;
      border-collapse: separate;
      border-spacing: 0;
      border-block-end: 1px solid var(--typeset-rule);
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
    }
    &:where(.typeset-scroll) {
      overflow-x: auto;
      margin-block-start: var(--typeset-flow);
    }
    &:where(.typeset-scroll > *) {
      margin-block-start: 0;
    }
    &:where(.typeset-scroll table) {
      width: max-content;
      max-width: none;
    }
    &:where(thead th) {
      font-weight: 500;
      text-align: start;
      white-space: nowrap;
      padding: 0.65em 1em;
    }
    &:where(:is(tbody, tfoot) :is(td, th)) {
      padding: 0.75em 1em;
      text-align: start;
      vertical-align: top;
      border-block-start: 1px solid var(--typeset-rule);
    }
    &:where(tbody th, tfoot th) {
      font-weight: 500;
    }
    &:where(th:first-child, td:first-child) {
      padding-inline-start: 0;
    }
    &:where(th[align="center"], td[align="center"]) {
      text-align: center;
    }
    &:where(th[align="right"], td[align="right"]) {
      text-align: end;
    }
    &:where(li > blockquote, li > table, li > figure) {
      margin-block-start: 0.5em;
    }
    &:where(li > pre) {
      margin-block-start: calc(0.5em / 0.875);
    }
    @media print {
      &:where(pre, table, blockquote, figure) {
        break-inside: avoid;
      }
      &:where(h1, h2, h3, h4) {
        break-after: avoid;
      }
    }
    @media (forced-colors: active) {
      &:where(:not(pre) > code) {
        border: 1px solid;
      }
    }
  }

  .typeset
    > :where(:first-child):not(
      :where(
        .not-typeset,
        [data-not-typeset],
        .not-typeset *,
        [data-not-typeset] *
      )
    ),
  .typeset
    > :where(:first-child)
    > :where(:first-child):not(
      :where(
        .not-typeset,
        [data-not-typeset],
        .not-typeset *,
        [data-not-typeset] *
      )
    ),
  .typeset
    :where(
      li > :first-child,
      blockquote > :first-child,
      td > :first-child,
      th > :first-child,
      dd > :first-child,
      figure > :first-child,
      figure > picture > img
    ):not(
      :where(
        .not-typeset,
        [data-not-typeset],
        .not-typeset *,
        [data-not-typeset] *
      )
    ) {
    margin-block-start: 0;
  }
}
